    "question": "Critical evaluation of Wagner-Meerwein Rearrangement: When 3,3-dimethylbut-1-ene is treated with dilute aqueous H2SO4, the major alcohol formed after rearrangement is:",
    "options": {
      "A": "2,3-Dimethylbutan-2-ol",
      "B": "3,3-Dimethylbutan-2-ol",
      "C": "3,3-Dimethylbutan-1-ol",
      "D": "2,3-Dimethylbutan-1-ol"
    },
    "optionsList": [
      "2,3-Dimethylbutan-2-ol",
      "3,3-Dimethylbutan-2-ol",
      "3,3-Dimethylbutan-1-ol",
      "2,3-Dimethylbutan-1-ol"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nCarbocation rearrangement (1,2-methide shift) during acid-catalyzed hydration of alkenes.\n\n2. GIVEN:\n(CH3)3C-CH=CH2 + H+ -> (CH3)3C-CH+-CH3 -> (CH3)2C+-CH(CH3)2 -> alcohol.\n\n3. FORMULA / PRINCIPLE:\nSecondary carbocation rearranges to more stable tertiary carbocation via 1,2-methyl shift.\n\n4. STEP-BY-STEP SOLUTION:\n1. Step 1: Electrophilic addition of H+ to the terminal double bond gives a secondary carbocation: (CH3)3C-CH+-CH3.\n2. Step 2: Adjacent to the positive carbon is a quaternary carbon carrying three methyl groups.\n3. Step 3: A 1,2-methide shift (:CH3-) occurs to relieve steric crowding and generate an exceptionally stable tertiary carbocation: (CH3)2C+-CH(CH3)2.\n4. Step 4: Nucleophilic attack of H2O followed by deprotonation yields 2,3-dimethylbutan-2-ol as the major product (>85%).\n\n5. FINAL ANSWER:\nOption A: 2,3-Dimethylbutan-2-ol\n\n6. WHY OTHER OPTIONS ARE WRONG:\nDirect hydration without rearrangement gives 3,3-dimethylbutan-2-ol as a minor product; rearrangement to 3\u00b0 carbocation dominates.",
    "solutionStructured": {
      "concept": "Carbocation rearrangement (1,2-methide shift) during acid-catalyzed hydration of alkenes.",
      "given": "(CH3)3C-CH=CH2 + H+ -> (CH3)3C-CH+-CH3 -> (CH3)2C+-CH(CH3)2 -> alcohol.",
      "formula": "Secondary carbocation rearranges to more stable tertiary carbocation via 1,2-methyl shift.",
      "stepByStep": "1. Step 1: Electrophilic addition of H+ to the terminal double bond gives a secondary carbocation: (CH3)3C-CH+-CH3.\n2. Step 2: Adjacent to the positive carbon is a quaternary carbon carrying three methyl groups.\n3. Step 3: A 1,2-methide shift (:CH3-) occurs to relieve steric crowding and generate an exceptionally stable tertiary carbocation: (CH3)2C+-CH(CH3)2.\n4. Step 4: Nucleophilic attack of H2O followed by deprotonation yields 2,3-dimethylbutan-2-ol as the major product (>85%).",
      "finalAnswer": "Option A: 2,3-Dimethylbutan-2-ol",
      "whyOtherOptionsWrong": "Direct hydration without rearrangement gives 3,3-dimethylbutan-2-ol as a minor product; rearrangement to 3\u00b0 carbocation dominates."
    },
