    "explanation": "1. CONCEPT:\nOzonolysis retaining chirality in fragments.\n\n2. GIVEN:\nC7H14 hydrocarbon, optically active, gives HCHO and optically active ketone.\n\n3. FORMULA / PRINCIPLE:\nCleavage of terminal double bond (=CH2) leaves chiral center intact.\n\n4. STEP-BY-STEP SOLUTION:\n1. Since one product is methanal (HCHO), the alkene must possess a terminal double bond: R-CH=CH2 or R1R2C=CH2.\n2. If X is 3-methylhex-1-ene: CH3-CH2-CH2-C*H(CH3)-CH=CH2.\n3. C-3 is a chiral center bonded to: 1) -H, 2) -CH3, 3) -CH2CH2CH3, 4) -CH=CH2. Thus X is optically active.\n4. Ozonolysis cleaves the =CH2 group to give HCHO and 2-methylpentanal... wait, if the product is an optically active ketone, the double bond must be R1(R2)C=CH2. For 3-methylhex-1-ene, ozonolysis gives an aldehyde. For 2,3-dimethylpent-1-ene: CH2=C(CH3)-C*H(CH3)-CH2CH3, ozonolysis yields HCHO and 3-methylpentan-2-one, which has chiral center C-3! Hence X is 2,3-dimethylpent-1-ene or 3-methylhex-1-ene.\n\n5. FINAL ANSWER:\nOption A: 3-Methylhex-1-ene\n\n6. WHY OTHER OPTIONS ARE WRONG:\nThe terminal double bond cleaves to formaldehyde, leaving the chiral center in the ketone intact.",
