    "explanation": "1. CONCEPT:\nStereospecific anti-addition of halogens to alkenes.\n\n2. GIVEN:\ntrans-But-2-ene + Br2 in CCl4.\n\n3. FORMULA / PRINCIPLE:\nAnti-addition to trans-alkene produces a meso compound with internal plane of symmetry.\n\n4. STEP-BY-STEP SOLUTION:\n1. Bromination of alkenes proceeds via formation of a cyclic bridged bromonium ion followed by backside nucleophilic attack by Br- (anti-addition).\n2. When bromine adds anti across trans-but-2-ene, the two chiral carbons (C-2 and C-3) receive bromine atoms from opposite faces.\n3. In the resulting Fischer projection, the molecule possesses an internal plane of symmetry and center of inversion.\n4. Consequently, the product is meso-2,3-dibromobutane, which is optically inactive by internal compensation.\n\n5. FINAL ANSWER:\nOption A: meso-2,3-Dibromobutane\n\n6. WHY OTHER OPTIONS ARE WRONG:\nAnti-addition on cis-alkene gives racemic pair; anti-addition on trans-alkene gives meso compound.",
