    "question": "When 2-bromobutane is treated with potassium tert-butoxide ((CH3)3CO- K+) in tert-butanol, the major elimination product is:",
    "options": {
      "A": "But-1-ene (Hofmann product)",
      "B": "trans-But-2-ene (Saytzeff product)",
      "C": "cis-But-2-ene",
      "D": "2-Methylpropene"
    },
    "optionsList": [
      "But-1-ene (Hofmann product)",
      "trans-But-2-ene (Saytzeff product)",
      "cis-But-2-ene",
      "2-Methylpropene"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nHofmann elimination with bulky, sterically hindered bases.\n\n2. GIVEN:\nCH3-CH(Br)-CH2-CH3 + (CH3)3CO- K+.\n\n3. FORMULA / PRINCIPLE:\nBulky base preferentially abstracts less sterically hindered proton from primary methyl group.\n\n4. STEP-BY-STEP SOLUTION:\n1. Potassium tert-butoxide ((CH3)3CO-) is a massive, sterically congested base.\n2. To eliminate HBr from 2-bromobutane, the base can abstract a proton from C-3 (secondary carbon) or from C-1 (primary methyl carbon).\n3. Because of its immense steric bulk, tert-butoxide cannot easily access the more congested C-3 proton.\n4. Instead, it abstracts the more accessible, unhindered primary proton from C-1, yielding the less substituted alkene but-1-ene as the major product (~73%).\n5. This is known as the Hofmann elimination rule.\n\n5. FINAL ANSWER:\nOption A: But-1-ene (Hofmann product)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nSmall bases (like ethoxide or KOH) give Saytzeff product (but-2-ene); bulky bases (like t-BuO-) give Hofmann product (but-1-ene).",
    "solutionStructured": {
      "concept": "Hofmann elimination with bulky, sterically hindered bases.",
      "given": "CH3-CH(Br)-CH2-CH3 + (CH3)3CO- K+.",
      "formula": "Bulky base preferentially abstracts less sterically hindered proton from primary methyl group.",
      "stepByStep": "1. Potassium tert-butoxide ((CH3)3CO-) is a massive, sterically congested base.\n2. To eliminate HBr from 2-bromobutane, the base can abstract a proton from C-3 (secondary carbon) or from C-1 (primary methyl carbon).\n3. Because of its immense steric bulk, tert-butoxide cannot easily access the more congested C-3 proton.\n4. Instead, it abstracts the more accessible, unhindered primary proton from C-1, yielding the less substituted alkene but-1-ene as the major product (~73%).\n5. This is known as the Hofmann elimination rule.",
      "finalAnswer": "Option A: But-1-ene (Hofmann product)",
      "whyOtherOptionsWrong": "Small bases (like ethoxide or KOH) give Saytzeff product (but-2-ene); bulky bases (like t-BuO-) give Hofmann product (but-1-ene)."
    },
