    "explanation": "1. CONCEPT:\nHigh-temperature allylic halogenation of alkenes.\n\n2. GIVEN:\nCH3-CH=CH2 + Cl2 (773 K, vapor phase).\n\n3. FORMULA / PRINCIPLE:\nAt high temperatures, free-radical allylic substitution predominates over electrophilic addition.\n\n4. STEP-BY-STEP SOLUTION:\n1. At low temperatures in liquid phase, Cl2 adds electrophilically across the C=C double bond to give 1,2-dichloropropane.\n2. At high temperatures (773 K / 500 \u00b0C), addition becomes reversible and free radical homolysis dominates.\n3. Chlorine radicals abstract an allylic hydrogen from the methyl group to form the resonance-stabilized allyl radical: CH2=CH-CH2. <-> .CH2-CH=CH2.\n4. The allyl radical then reacts with Cl2 to yield 3-chloroprop-1-ene (allyl chloride) while regenerating the chlorine radical.\n\n5. FINAL ANSWER:\nOption A: 3-Chloroprop-1-ene (allyl chloride)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nHigh temperature favors radical substitution at the weak allylic C-H bond rather than electrophilic addition.",
